import time

def time_execution(func):
    def wrapped_function(*args, **kwargs):
        start_time = time.time()
        result = func(*args, **kwargs)
        end_time = time.time()
        duration = end_time - start_time
        print(f"Execution time: {duration:.2f} seconds")
        return result

    return wrapped_function

